package main

import (
	"fmt"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"image"
	"os"
)

func main() {
	test := func(path string) {
		f, err := os.Open(path)
		if err != nil { fmt.Printf("%s: open err %v\n", path, err); return }
		defer f.Close()
		img, format, err := image.Decode(f)
		if err != nil {
			fmt.Printf("%s: format=%s err=%v\n", path, format, err)
			return
		}
		fmt.Printf("%s: format=%s bounds=%v\n", path, format, img.Bounds())
	}
