	test("assets/j0.JPG")
	test("assets/g1.gif")
	test("assets/w0.webp")
	test("assets/t0.tif")
	test("/tmp/a.jpeg")
	test("/tmp/fake.jpg")
}
GO
go run /tmp/gomain.go
