            Ok(s.to_string())
        } else {
            Err(format!("Invalid size format: '{}'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes", s))
        }
    }
}

fn parse_min_savings_value(s: &str) -> MinSavings {
    if s.ends_with('%') {
        let num_part = &s[..s.len()-1];
        if let Ok(v) = num_part.parse::<f64>() {
            return MinSavings::Percent(v);
        }
    }
    // try parse as bytesize or plain number
    if let Ok(v) = parse_max_size(s) {
        // if original had alphabetic, it's size, else plain number we already parsed as bytes
        return MinSavings::Bytes(v);
    }
    // fallback plain number
    if let Ok(v) = s.parse::<f64>() {
        return MinSavings::Bytes(v as u64);
    }
    MinSavings::Bytes(0)
}

#[derive(Clone, Debug)]
enum MinSavings {
    Percent(f64),
    Bytes(u64),
}

fn detect_format(path: &Path) -> Option<String> {
    // read first bytes to detect format
    let mut file = fs::File::open(path).ok()?;
    let mut buf = [0u8; 32];
    use std::io::Read;
    let n = file.read(&mut buf).ok()?;
    if n < 4 { return None; }
    // PNG magic: 89 50 4E 47 0D 0A 1A 0A
    if buf.starts_with(&[0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]) {
        return Some("png".to_string());
    }
    // JPEG magic: FF D8 FF
    if buf[0]==0xFF && buf[1]==0xD8 && buf[2]==0xFF {
        return Some("jpeg".to_string());
    }
    // GIF magic: GIF87a or GIF89a
    if buf.starts_with(b"GIF87a") || buf.starts_with(b"GIF89a") {
        return Some("gif".to_string());
    }
    // WEBP: RIFF....WEBP
    if buf[0..4]==*b"RIFF" && n>=12 && buf[8..12]==*b"WEBP" {
        return Some("webp".to_string());
    }
    // BMP magic: BM
    if buf[0]==0x42 && buf[1]==0x4D {
        // Check if original would treat BMP as valid? We saw real BMP fails. So we should return None for BMP to match original (BMP not supported)
        // But PNG data with .bmp extension would have been detected as PNG earlier, so BMP magic not needed.
        return None;
    }
    // TIFF magic: II*\0 or MM\0*
    if (buf[0]==0x49 && buf[1]==0x49 && buf[2]==0x2A && buf[3]==0x00) || (buf[0]==0x4D && buf[1]==0x4D && buf[2]==0x00 && buf[3]==0x2A) {
        // Original fails for this TIFF? Let's treat as None to cause skip (as observed)
        return None;
    }
    // For other formats, try extension fallback? We should also accept files that have known image extensions even if magic not recognized? But for our needs, we have PNG, JPEG, GIF, WEBP covered.
    // If file contains PNG but with .tif extension, PNG magic will detect.
    // For JPEG with .png extension etc.
    None
}

fn compute_common_ancestor(paths: &[PathBuf]) -> Option<PathBuf> {
    if paths.is_empty() { return None; }
    // canonicalize to absolute?
    let mut ancestors: Vec<Vec<Component>> = Vec::new();
    for p in paths {
        let abs = if p.is_absolute() { p.clone() } else { std::env::current_dir().unwrap().join(p) };
        let components: Vec<Component> = abs.components().collect();
        // Remove last component (file name) for file paths? Actually we want common ancestor of files, so we consider their parent directories? Let's see earlier: for single file /tmp/base1/x.png, base = /tmp/base1 (parent). For two files /tmp/base1/x.png and /tmp/base2/y.png, base = /tmp (common ancestor of files). If we include file name in ancestor computation, common ancestor of /tmp/base1/x.png and /tmp/base2/y.png is /tmp (since /tmp/base1 vs /tmp/base2 diverge). That's same as if we used parent directories only? For single file, parent is /tmp/base1, but common ancestor of files including file name would be /tmp/base1/x.png itself? Actually single file case, common ancestor should be parent, not file itself. So we should use parent directories for common ancestor.
        let parent = abs.parent().unwrap_or(Path::new("/"));
        let parent_components: Vec<Component> = parent.components().collect();
        ancestors.push(parent_components);
    }
    // Find longest common prefix among ancestors
    if ancestors.is_empty() { return None; }
    let mut common: Vec<Component> = Vec::new();
    for i in 0.. {
        if i >= ancestors[0].len() { break; }
        let comp = ancestors[0][i];
        if ancestors.iter().all(|a| i < a.len() && a[i]==comp) {
            common.push(comp);
        } else {
            break;
        }
    }
    if common.is_empty() {
        Some(PathBuf::from("/"))
    } else {
        let mut path = PathBuf::new();
        for c in common {
            path.push(c.as_os_str());
        }
        Some(path)
    }
}

fn format_size(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024*1024 {
        let v = bytes as f64 / 1024.0;
        format!("{:.1} KiB", v)
    } else if bytes < 1024*1024*1024 {
        let v = bytes as f64 / (1024.0*1024.0);
        format!("{:.1} MiB", v)
    } else if bytes < 1024*1024*1024*1024 {
        let v = bytes as f64 / (1024.0*1024.0*1024.0);
        format!("{:.1} GiB", v)
    } else {
        let v = bytes as f64 / (1024.0*1024.0*1024.0*1024.0);
        format!("{:.1} TiB", v)
    }
}

fn format_size_signed(diff: i64) -> String {
    if diff == 0 {
        return "0 B".to_string();
    }
    let sign = if diff > 0 { "+" } else { "-" };
    let abs = diff.abs() as u64;
    let formatted = format_size(abs);
    format!("{}{}", sign, formatted)
}

fn num_cpus() -> usize {
    std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1)
}

