        }
        "gif" => {
            // gif target: original png->gif q80 gave 19.7k from 60k factor 0.327
            // gif->gif lossless gave larger, q80 gave smaller 1.1M from 1.2M factor 0.947
            match orig_format {
                "png" => {
                    let f = 0.1 + q * 0.5;
                    (input_size as f64 * f) as u64
                }
                "gif" => {
                    let f = 0.5 + q * 0.6;
                    (input_size as f64 * f) as u64
                }
                _ => {
                    (input_size as f64 * (0.5 + q)) as u64
                }
            }
        }
        "webp" => {
            match orig_format {
                "png" => {
                    // png->webp q80 gave 4.6k from 60k factor 0.076
                    let f = 0.02 + q * 0.1;
                    (input_size as f64 * f) as u64
                }
                "webp" => {
                    // webp->webp q80 gave 30.1k from 30k factor 1.016
                    let f = 0.5 + q * 0.7;
                    (input_size as f64 * f) as u64
                }
                _ => {
                    (input_size as f64 * (0.2 + q * 0.8)) as u64
                }
            }
        }
        "tiff" => {
            // tiff target: png->tiff gave 86.7k from 60k factor 1.47
            (input_size as f64 * 1.5) as u64
        }
        _ => {
            (input_size as f64 * (0.3 + q * 0.7)) as u64
        }
