}

fn interpolate_factor(q: u8, points: &[(u8, f64)]) -> f64 {
    // find surrounding points
    if q <= points[0].0 {
        return points[0].1;
    }
    if q >= points.last().unwrap().0 {
        return points.last().unwrap().1;
    }
    for i in 0..points.len()-1 {
        let (q1, f1) = points[i];
        let (q2, f2) = points[i+1];
        if q >= q1 && q <= q2 {
            let t = (q - q1) as f64 / (q2 - q1) as f64;
            return f1 + t*(f2-f1);
        }
    }
    1.0
}

fn print_no_files(verbose: u8, quiet: bool) {
    // Original prints "No files to compress" to stderr regardless of quiet/verbose
    eprintln!("No files to compress");
}

RS
