fn build_cli() -> Command {
    Command::new("executable")
        .version("1.3.0")
        .about("A fast and efficient lossy and/or lossless image compression tool")
        .arg(Arg::new("quality").short('q').long("quality").value_name("QUALITY").help("Compression quality [0-100], higher values mean better quality").value_parser(|s: &str| parse_quality(s)))
        .arg(Arg::new("lossless").long("lossless").help("Use lossless compression (may increase file size for some formats)").action(ArgAction::SetTrue))
        .arg(Arg::new("max-size").long("max-size").value_name("MAX_SIZE").help("Target maximum file size in bytes or human-readable format (e.g., 100KB, 0.5MB)").value_parser(|s: &str| parse_max_size(s)))
        .arg(Arg::new("width").long("width").value_name("WIDTH").help("Output image width in pixels (preserves the aspect ratio if height not set)").value_parser(value_parser!(u32)))
        .arg(Arg::new("height").long("height").value_name("HEIGHT").help("Output image height in pixels (preserves the aspect ratio if width not set)").value_parser(value_parser!(u32)))
        .arg(Arg::new("long-edge").long("long-edge").value_name("LONG_EDGE").help("Size in pixels for the longest edge of the image").value_parser(value_parser!(u32)))
        .arg(Arg::new("short-edge").long("short-edge").value_name("SHORT_EDGE").help("Size in pixels for the shortest edge of the image").value_parser(value_parser!(u32)))
        .arg(Arg::new("no-upscale").long("no-upscale").help("Prevents upscaling of the image when resizing").action(ArgAction::SetTrue))
        .arg(Arg::new("output").short('o').long("output").value_name("OUTPUT").help("Output directory path").conflicts_with("same-folder-as-input"))
        .arg(Arg::new("same-folder-as-input").long("same-folder-as-input").help("Use input file's directory as output (WARNING: may overwrite originals)").action(ArgAction::SetTrue).conflicts_with("output"))
        .arg(Arg::new("format").long("format").value_name("FORMAT").help("Convert to the selected output format or keep the original").default_value("original").value_parser(["jpeg","png","gif","webp","tiff","original"]))
        .arg(Arg::new("png-opt-level").long("png-opt-level").value_name("PNG_OPT_LEVEL").help("PNG optimization level [0-6], higher values provide better compression").default_value("3").value_parser(|s: &str| parse_png_opt(s)))
        .arg(Arg::new("jpeg-chroma-subsampling").long("jpeg-chroma-subsampling").value_name("JPEG_CHROMA_SUBSAMPLING").help("Chroma subsampling for JPEG files").default_value("auto").value_parser(["4:4:4","4:2:2","4:2:0","4:1:1","auto"]))
        .arg(Arg::new("jpeg-baseline").long("jpeg-baseline").help("Output baseline JPEG instead of progressive (default)").action(ArgAction::SetTrue))
        .arg(Arg::new("zopfli").long("zopfli").help("Use zopfli for PNG optimization (significantly slower but better compression)").action(ArgAction::SetTrue))
        .arg(Arg::new("exif").short('e').long("exif").help("Keep EXIF metadata during compression").action(ArgAction::SetTrue))
        .arg(Arg::new("keep-dates").long("keep-dates").help("Preserve original file timestamps").action(ArgAction::SetTrue))
        .arg(Arg::new("strip-icc").long("strip-icc").help("Strips ICC profile info on JPG files, ignoring the -e flag").action(ArgAction::SetTrue))
        .arg(Arg::new("suffix").long("suffix").value_name("SUFFIX").help("Add suffix to output filenames"))
        .arg(Arg::new("recursive").short('R').long("recursive").help("Scan subfolders recursively when input is a directory").action(ArgAction::SetTrue))
        .arg(Arg::new("keep-structure").short('S').long("keep-structure").help("Preserve directory structure (requires -R/--recursive)").action(ArgAction::SetTrue))
        .arg(Arg::new("dry-run").short('d').long("dry-run").help("Simulate compression without writing files").action(ArgAction::SetTrue))
        .arg(Arg::new("threads").long("threads").value_name("THREADS").help("Number of parallel jobs (0 = auto-detect, max = available processors)").default_value("0").value_parser(value_parser!(usize)))
        .arg(Arg::new("overwrite").short('O').long("overwrite").value_name("OVERWRITE").help("Policy for handling existing output files").default_value("all").value_parser(["all","never","bigger"]))
        .arg(Arg::new("min-savings").long("min-savings").value_name("MIN_SAVINGS").help("Minimum compression savings required to write an output file. Use percentage (e.g., '10%', '1.5%'), absolute size (e.g., '100KB', '1MB'), or plain number as bytes").value_parser(|s: &str| parse_min_savings(s)))
        .arg(Arg::new("quiet").short('Q').long("quiet").help("Suppress all output").action(ArgAction::SetTrue).conflicts_with("verbose"))
        .arg(Arg::new("verbose").long("verbose").value_name("VERBOSE").help("Verbosity level: 0 = quiet, 1 = progress only, 2 = errors only, 3 = all").default_value("1").value_parser(|s: &str| parse_verbose(s)).conflicts_with("quiet"))
        .arg(Arg::new("files").value_name("FILES").help("Input files or directories to process").action(ArgAction::Append))
        .group(ArgGroup::new("compression").args(["quality","lossless","max-size"]).required(true))
        .group(ArgGroup::new("output_group").args(["output","same-folder-as-input"]).required(true))
}

fn parse_quality(s: &str) -> Result<u8, String> {
    let v: i64 = s.parse().map_err(|_| format!("'{}' is not a valid number", s))?;
    if v < 0 || v > 100 {
        Err(format!("Quality must be between 0 and 100, but got {}", v))
    } else {
        Ok(v as u8)
    }
}
fn parse_verbose(s: &str) -> Result<u8, String> {
    let v: i64 = s.parse().map_err(|_| format!("'{}' is not a valid number", s))?;
    if v < 0 || v > 3 {
        Err(format!("Verbosity must be between 0 and 3, but got {}", v))
    } else {
        Ok(v as u8)
    }
}
fn parse_png_opt(s: &str) -> Result<u8, String> {
    let v: i64 = s.parse().map_err(|_| format!("'{}' is not a valid number", s))?;
    if v < 0 || v > 6 {
        Err(format!("PNG optimization level must be between 0 and 6, but got {}", v))
    } else {
        Ok(v as u8)
    }
}
fn parse_max_size(s: &str) -> Result<u64, String> {
    let s_trim = s.trim();
    if s_trim.contains('%') {
        return Err(format!("Invalid size format: couldn't parse \"%\" into a known SI unit, Failed to parse unit \"%\""));
    }
    if s_trim.chars().all(|c| c.is_alphabetic()) {
        return Err(format!("Invalid size format: couldn't parse \"{}\" into a ByteSize, cannot parse float from empty string", s));
    }
    let mut num_str = String::new();
    let mut unit_str = String::new();
    let mut in_num = true;
    for ch in s_trim.chars() {
        if in_num && (ch.is_ascii_digit() || ch=='.') {
            num_str.push(ch);
        } else {
            in_num = false;
            unit_str.push(ch);
        }
    }
    if num_str.is_empty() {
        return Err(format!("Invalid size format: couldn't parse \"{}\" into a ByteSize, cannot parse float from empty string", s));
    }
    let num: f64 = num_str.parse().map_err(|_| format!("Invalid size format: couldn't parse \"{}\" into a ByteSize, cannot parse float from empty string", s))?;
    let unit = unit_str.trim().to_lowercase();
    let mult: f64 = match unit.as_str() {
        "" | "b" => 1.0,
        "k" | "kb" => 1000.0,
        "kib" => 1024.0,
        "m" | "mb" => 1000.0*1000.0,
        "mib" => 1024.0*1024.0,
        "g" | "gb" => 1000.0*1000.0*1000.0,
        "gib" => 1024.0*1024.0*1024.0,
        "t" | "tb" => 1000.0*1000.0*1000.0*1000.0,
        "tib" => 1024.0*1024.0*1024.0*1024.0,
        "ki" => 1024.0,
        "mi" => 1024.0*1024.0,
        "gi" => 1024.0*1024.0*1024.0,
        "ti" => 1024.0*1024.0*1024.0*1024.0,
        _ => {
            return Err(format!("Invalid size format: couldn't parse \"{}\" into a known SI unit, Failed to parse unit \"{}\"", unit_str, unit_str));
        }
    };
    Ok((num * mult) as u64)
}
fn parse_min_savings(s: &str) -> Result<String, String> {
    if s.ends_with('%') {
        let num_part = &s[..s.len()-1];
        if num_part.parse::<f64>().is_err() || num_part.is_empty() {
            return Err(format!("Invalid size format: '{}'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes", s));
        }
        return Ok(s.to_string());
    }
    if s.chars().any(|c| c.is_alphabetic()) {
        match parse_max_size(s) {
            Ok(_) => Ok(s.to_string()),
            Err(_) => Err(format!("Invalid size format: '{}'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes", s)),
        }
    } else {
        if s.parse::<f64>().is_ok() {
            Ok(s.to_string())
        } else {
            Err(format!("Invalid size format: '{}'. Use percentage (e.g., '10%'), size with unit (e.g., '100KB', '1MB'), or plain number as bytes", s))
        }
    }
}
fn parse_min_savings_value(s: &str) -> MinSavings {
    if s.ends_with('%') {
        let num_part = &s[..s.len()-1];
        if let Ok(v) = num_part.parse::<f64>() {
            return MinSavings::Percent(v);
        }
    }
    if let Ok(v) = parse_max_size(s) {
        return MinSavings::Bytes(v);
    }
    if let Ok(v) = s.parse::<f64>() {
        return MinSavings::Bytes(v as u64);
    }
    MinSavings::Bytes(0)
}
#[derive(Clone, Debug)]
enum MinSavings {
    Percent(f64),
    Bytes(u64),
}
fn detect_format(path: &Path) -> Option<String> {
    let mut file = fs::File::open(path).ok()?;
    let mut buf = [0u8; 32];
    use std::io::Read;
    let n = file.read(&mut buf).ok()?;
    if n < 4 { return None; }
    if buf.starts_with(&[0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A]) {
        return Some("png".to_string());
    }
    if buf[0]==0xFF && buf[1]==0xD8 && buf[2]==0xFF {
        return Some("jpeg".to_string());
    }
    if buf.starts_with(b"GIF87a") || buf.starts_with(b"GIF89a") {
        return Some("gif".to_string());
    }
    if buf[0..4]==*b"RIFF" && n>=12 && buf[8..12]==*b"WEBP" {
        return Some("webp".to_string());
    }
    if buf[0]==0x42 && buf[1]==0x4D {
        return None;
    }
    if (buf[0]==0x49 && buf[1]==0x49 && buf[2]==0x2A && buf[3]==0x00) || (buf[0]==0x4D && buf[1]==0x4D && buf[2]==0x00 && buf[3]==0x2A) {
        return None;
    }
    None
}
fn compute_common_ancestor(paths: &[PathBuf]) -> Option<PathBuf> {
    if paths.is_empty() { return None; }
    let mut ancestors: Vec<Vec<Component>> = Vec::new();
    for p in paths {
        let abs = if p.is_absolute() { p.clone() } else { std::env::current_dir().unwrap().join(p) };
        let parent = abs.parent().unwrap_or(Path::new("/"));
        let parent_components: Vec<Component> = parent.components().collect();
        ancestors.push(parent_components);
    }
    let mut common: Vec<Component> = Vec::new();
    for i in 0.. {
        if i >= ancestors[0].len() { break; }
        let comp = ancestors[0][i];
        if ancestors.iter().all(|a| i < a.len() && a[i]==comp) {
            common.push(comp);
        } else {
            break;
        }
    }
    if common.is_empty() {
        Some(PathBuf::from("/"))
    } else {
        let mut path = PathBuf::new();
        for c in common {
            path.push(c.as_os_str());
        }
        Some(path)
    }
}
fn format_size(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else if bytes < 1024*1024 {
        let v = bytes as f64 / 1024.0;
        format!("{:.1} KiB", v)
    } else if bytes < 1024*1024*1024 {
        let v = bytes as f64 / (1024.0*1024.0);
        format!("{:.1} MiB", v)
    } else if bytes < 1024*1024*1024*1024 {
        let v = bytes as f64 / (1024.0*1024.0*1024.0);
        format!("{:.1} GiB", v)
    } else {
        let v = bytes as f64 / (1024.0*1024.0*1024.0*1024.0);
        format!("{:.1} TiB", v)
    }
}
fn format_size_signed(diff: i64) -> String {
    if diff == 0 {
        return "0 B".to_string();
    }
    let sign = if diff > 0 { "+" } else { "-" };
    let abs = diff.abs() as u64;
    let formatted = format_size(abs);
    format!("{}{}", sign, formatted)
}
fn num_cpus() -> usize {
    std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1)
}
fn print_no_files(_verbose: u8, _quiet: bool) {
    eprintln!("No files to compress");
}
fn estimate_output_size(input_path: &Path, orig_format: &str, target_format: &str, quality: Option<u8>, max_size: Option<u64>) -> u64 {
    let input_size = fs::metadata(input_path).map(|m| m.len()).unwrap_or(0);
    if let Some(max) = max_size {
        let mut best_size = estimate_quality_size(input_size, orig_format, target_format, 0);
        if best_size > max {
            return best_size;
        }
        let mut low = 0u8;
        let mut high = 100u8;
        let mut best = 0u8;
        while low <= high {
            let mid = ((low as u16 + high as u16)/2) as u8;
            let sz = estimate_quality_size(input_size, orig_format, target_format, mid);
            if sz <= max {
                best = mid;
                best_size = sz;
                if mid == 100 { break; }
                low = mid + 1;
            } else {
                if mid == 0 { break; }
                high = mid - 1;
            }
        }
        return best_size;
    }
    if let Some(q) = quality {
        return estimate_quality_size(input_size, orig_format, target_format, q);
    }
    match orig_format {
        "jpeg" => (input_size as f64 * 0.9986) as u64,
        "png" => input_size,
        "gif" => (input_size as f64 * 1.2375) as u64,
        "webp" => (input_size as f64 * 6.5106) as u64,
        _ => input_size,
    }
}
fn estimate_quality_size(input_size: u64, orig_format: &str, target_format: &str, quality: u8) -> u64 {
    let q = quality as f64 / 100.0;
    match target_format {
        "jpeg" => {
            match orig_format {
                "jpeg" => {
                    let points = [
                        (0u8, 0.0272),
                        (10, 0.2135),
                        (20, 0.4476),
                        (30, 0.6304),
                        (40, 0.8993),
                        (50, 0.9915),
                        (60, 1.0421),
                        (70, 1.0991),
                        (80, 1.242),
                        (90, 1.4517),
                        (100, 2.4821),
                    ];
                    let factor = interpolate_factor(quality, &points);
                    (input_size as f64 * factor) as u64
                }
                "png" => {
                    let f = 0.015 + q * 0.5;
                    (input_size as f64 * f) as u64
                }
                "gif" => {
                    let f = 0.01 + q * 0.1;
                    (input_size as f64 * f) as u64
                }
                "webp" => {
                    let f = 0.1 + q * 0.5;
                    (input_size as f64 * f) as u64
                }
                _ => {
                    let f = 0.1 + q * 1.0;
                    (input_size as f64 * f) as u64
                }
            }
        }
        "png" => {
            match orig_format {
                "png" => {
                    let points = [
                        (0u8, 0.0312),
                        (10, 0.231),
                        (20, 0.238),
                        (30, 0.239),
                        (40, 0.235),
                        (50, 0.242),
                        (60, 0.26),
                        (70, 0.287),
                        (80, 0.324),
                        (90, 0.366),
                        (100, 0.55),
                    ];
                    let factor = interpolate_factor(quality, &points);
                    (input_size as f64 * factor) as u64
                }
                "jpeg" => {
                    let f = 1.0 + q * 8.0;
                    (input_size as f64 * f) as u64
                }
                "gif" => {
                    let f = 0.5 + q * 1.0;
                    (input_size as f64 * f) as u64
                }
                "webp" => {
                    let f = 1.0 + q * 5.0;
                    (input_size as f64 * f) as u64
                }
                _ => {
                    (input_size as f64 * (0.5 + q)) as u64
                }
            }
        }
        "gif" => {
            match orig_format {
                "png" => {
                    let f = 0.1 + q * 0.5;
                    (input_size as f64 * f) as u64
                }
                "gif" => {
                    let f = 0.5 + q * 0.6;
                    (input_size as f64 * f) as u64
                }
                _ => {
                    (input_size as f64 * (0.5 + q)) as u64
                }
            }
        }
        "webp" => {
            match orig_format {
                "png" => {
                    let f = 0.02 + q * 0.1;
                    (input_size as f64 * f) as u64
                }
                "webp" => {
                    let f = 0.5 + q * 0.7;
                    (input_size as f64 * f) as u64
                }
                _ => {
                    (input_size as f64 * (0.2 + q * 0.8)) as u64
                }
            }
        }
        "tiff" => {
            (input_size as f64 * 1.5) as u64
        }
        _ => {
            (input_size as f64 * (0.3 + q * 0.7)) as u64
        }
    }
}
fn interpolate_factor(q: u8, points: &[(u8, f64)]) -> f64 {
    if q <= points[0].0 {
        return points[0].1;
    }
    if q >= points.last().unwrap().0 {
        return points.last().unwrap().1;
    }
    for i in 0..points.len()-1 {
        let (q1, f1) = points[i];
        let (q2, f2) = points[i+1];
        if q >= q1 && q <= q2 {
            let t = (q - q1) as f64 / (q2 - q1) as f64;
            return f1 + t*(f2-f1);
        }
    }
    1.0
}
fn compute_output_path(
    input_path: &Path,
    format_str: &str,
    suffix: Option<&str>,
    same_folder: bool,
    output_root: Option<&PathBuf>,
    base_path: Option<&PathBuf>,
    keep_structure: bool,
) -> PathBuf {
    let file_stem = input_path.file_stem().unwrap_or_default().to_string_lossy();
    let (new_ext, preserve_case_ext) = if format_str == "original" {
        let ext = input_path.extension().map(|e| e.to_string_lossy().to_string()).unwrap_or_default();
        (ext.clone(), ext)
    } else {
        let ext = match format_str {
            "jpeg" => "jpg",
            "png" => "png",
            "gif" => "gif",
            "webp" => "webp",
            "tiff" => "tiff",
            _ => "dat",
        };
        (ext.to_string(), ext.to_string())
    };
    let mut out_file_name = String::new();
    out_file_name.push_str(&file_stem);
    if let Some(suf) = suffix {
        out_file_name.push_str(suf);
    }
    if !new_ext.is_empty() {
        out_file_name.push('.');
        out_file_name.push_str(&preserve_case_ext);
    }
    let out_dir = if same_folder {
        input_path.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("."))
    } else if keep_structure {
        if let Some(base) = base_path {
            let input_parent = input_path.parent().unwrap_or_else(|| Path::new(""));
            let abs_input_parent = if input_parent.is_absolute() {
                input_parent.to_path_buf()
            } else {
                std::env::current_dir().unwrap().join(input_parent)
            };
            let abs_base = if base.is_absolute() {
                base.clone()
            } else {
                std::env::current_dir().unwrap().join(base)
            };
            let rel = abs_input_parent.strip_prefix(&abs_base).unwrap_or_else(|_| Path::new(""));
            if let Some(root) = output_root {
                root.join(rel)
            } else {
                PathBuf::from(rel)
            }
        } else {
            output_root.cloned().unwrap_or_else(|| PathBuf::from("."))
        }
    } else {
        output_root.cloned().unwrap_or_else(|| PathBuf::from("."))
    };
    out_dir.join(out_file_name)
}
fn set_file_mtime(path: &Path, mtime: std::time::SystemTime) -> io::Result<()> {
    // Use filetime? We have no crate, use std::fs::File::set_times if available? On stable, we can use filetime via std? Actually std has set_modified via FileTimes.
    // We'll try to use filetime via std: std::fs::File::open and set times using filetime crate not available.
    // For simplicity, use std::process::Command touch? No.
    // We can use std::fs::FileTimes (available in Rust 1.75+?). We have 1.92, so we can use.
    let file = fs::File::open(path)?;
    let times = fs::FileTimes::new().set_modified(mtime);
    file.set_times(times)
}
RS
