                        (30, 0.6304),
                        (40, 0.8993),
                        (50, 0.9915),
                        (60, 1.0421),
                        (70, 1.0991),
                        (80, 1.242),
                        (90, 1.4517),
                        (100, 2.4821),
                    ];
                    let factor = interpolate_factor(quality, &points);
                    (input_size as f64 * factor) as u64
                }
                "png" => {
                    let f = 0.015 + q * 0.5;
