                    (input_size as f64 * f) as u64
                }
                "webp" => {
                    let f = 0.1 + q * 0.5;
                    (input_size as f64 * f) as u64
                }
                _ => {
                    let f = 0.1 + q * 1.0;
                    (input_size as f64 * f) as u64
                }
            }
        }
        "png" => {
            match orig_format {
