#[derive(Clone, Debug)]
enum MinSavings {
    Percent(f64),
    Bytes(u64),
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum Status { Success, Skipped, Error }

#[derive(Debug)]
struct FileResult {
