    let same_folder = matches.get_flag("same-folder-as-input");

    let format_str: String = matches.get_one::<String>("format").unwrap().clone();
    let suffix: Option<String> = matches.get_one::<String>("suffix").cloned();
    let recursive = matches.get_flag("recursive");
    let keep_structure = matches.get_flag("keep-structure");
    let dry_run = matches.get_flag("dry-run");
    let threads: usize = *matches.get_one::<usize>("threads").unwrap_or(&0);
    let overwrite_str: String = matches.get_one::<String>("overwrite").unwrap().clone();
    let min_savings_raw: Option<String> = matches.get_one::<String>("min-savings").cloned();
    let keep_dates = matches.get_flag("keep-dates");

    let input_files: Vec<String> = matches.get_many::<String>("files").map(|v| v.cloned().collect()).unwrap_or_default();

    if input_files.is_empty() {
        eprintln!("No files to compress");
        std::process::exit(0);
    }

    let mut collected: Vec<PathBuf> = Vec::new();
    let mut seen: HashSet<PathBuf> = HashSet::new();

    for inp in &input_files {
        let p = PathBuf::from(inp);
        if !p.exists() {
            continue;
        }
        if p.is_file() {
            if detect_format(&p).is_some() {
                let canonical = fs::canonicalize(&p).unwrap_or_else(|_| p.clone());
                if seen.insert(canonical) {
                    collected.push(p);
                }
            }
        } else if p.is_dir() {
            if recursive {
                for entry in WalkDir::new(&p).follow_links(false).into_iter().filter_map(|e| e.ok()) {
                    let path = entry.path().to_path_buf();
                    if path.is_file() && detect_format(&path).is_some() {
                        let canonical = fs::canonicalize(&path).unwrap_or_else(|_| path.clone());
                        if seen.insert(canonical) {
                            collected.push(path);
                        }
                    }
                }
            } else {
                if let Ok(rd) = fs::read_dir(&p) {
                    for entry in rd.filter_map(|e| e.ok()) {
                        let path = entry.path();
                        if path.is_file() && detect_format(&path).is_some() {
                            let canonical = fs::canonicalize(&path).unwrap_or_else(|_| path.clone());
                            if seen.insert(canonical) {
                                collected.push(path);
                            }
                        }
                    }
                }
            }
        }
