        .arg(Arg::new("same-folder-as-input").long("same-folder-as-input").help("Use input file's directory as output (WARNING: may overwrite originals)").action(ArgAction::SetTrue).conflicts_with("output"))
        .arg(Arg::new("format").long("format").value_name("FORMAT").help("Convert to the selected output format or keep the original").long_help("Convert to the selected output format or keep the original").default_value("original").value_parser(["jpeg","png","gif","webp","tiff","original"]))
        .arg(Arg::new("png-opt-level").long("png-opt-level").value_name("PNG_OPT_LEVEL").help("PNG optimization level [0-6], higher values provide better compression").long_help("PNG optimization level [0-6], higher values provide better compression").default_value("3").value_parser(|s: &str| parse_png_opt(s)))
        .arg(Arg::new("jpeg-chroma-subsampling").long("jpeg-chroma-subsampling").value_name("JPEG_CHROMA_SUBSAMPLING").help("Chroma subsampling for JPEG files").long_help("Chroma subsampling for JPEG files").default_value("auto").value_parser(["4:4:4","4:2:2","4:2:0","4:1:1","auto"]))
