use std::path::{Path, PathBuf};
use std::fs;
use std::io;
use clap::{Arg, ArgAction, ArgGroup, Command, value_parser};
use rayon::prelude::*;
use walkdir::WalkDir;
use std::collections::HashSet;
use std::sync::{Arc, Mutex};

#[derive(Clone, Debug)]
enum MinSavings {
    Percent(f64),
    Bytes(u64),
}

#[derive(Clone, Copy, PartialEq, Debug)]
enum Status { Success, Skipped, Error }

#[derive(Debug)]
struct FileResult {
    input_path: PathBuf,
    output_path: PathBuf,
    input_size: u64,
    output_size: u64,
    status: Status,
    message: Option<String>,
}

fn main() {
    let matches = build_cli().get_matches();

    let quiet = matches.get_flag("quiet");
    let verbose_level: u8 = if quiet { 0 } else { *matches.get_one::<u8>("verbose").unwrap_or(&1) };

    let quality: Option<u8> = matches.get_one::<u8>("quality").copied();
    let max_size: Option<u64> = matches.get_one::<u64>("max-size").copied();

    let output_dir: Option<String> = matches.get_one::<String>("output").cloned();
    let same_folder = matches.get_flag("same-folder-as-input");

    let format_str: String = matches.get_one::<String>("format").unwrap().clone();
    let suffix: Option<String> = matches.get_one::<String>("suffix").cloned();
    let recursive = matches.get_flag("recursive");
    let keep_structure = matches.get_flag("keep-structure");
    let dry_run = matches.get_flag("dry-run");
    let threads: usize = *matches.get_one::<usize>("threads").unwrap_or(&0);
    let overwrite_str: String = matches.get_one::<String>("overwrite").unwrap().clone();
    let min_savings_raw: Option<String> = matches.get_one::<String>("min-savings").cloned();
    let keep_dates = matches.get_flag("keep-dates");

    let input_files: Vec<String> = matches.get_many::<String>("files").map(|v| v.cloned().collect()).unwrap_or_default();

    if input_files.is_empty() {
        eprintln!("No files to compress");
        std::process::exit(0);
    }

    let mut collected: Vec<PathBuf> = Vec::new();
    let mut seen: HashSet<PathBuf> = HashSet::new();

    for inp in &input_files {
        let p = PathBuf::from(inp);
        if !p.exists() {
            continue;
        }
        if p.is_file() {
            if detect_format(&p).is_some() {
                let canonical = fs::canonicalize(&p).unwrap_or_else(|_| p.clone());
                if seen.insert(canonical) {
                    collected.push(p);
                }
            }
        } else if p.is_dir() {
            if recursive {
                for entry in WalkDir::new(&p).follow_links(false).into_iter().filter_map(|e| e.ok()) {
                    let path = entry.path().to_path_buf();
                    if path.is_file() && detect_format(&path).is_some() {
                        let canonical = fs::canonicalize(&path).unwrap_or_else(|_| path.clone());
                        if seen.insert(canonical) {
                            collected.push(path);
                        }
                    }
                }
            } else {
                if let Ok(rd) = fs::read_dir(&p) {
                    for entry in rd.filter_map(|e| e.ok()) {
                        let path = entry.path();
                        if path.is_file() && detect_format(&path).is_some() {
                            let canonical = fs::canonicalize(&path).unwrap_or_else(|_| path.clone());
                            if seen.insert(canonical) {
                                collected.push(path);
                            }
                        }
                    }
                }
            }
        }
    }

    if collected.is_empty() {
        eprintln!("Unable to compute the base path for the files.");
        std::process::exit(255);
    }

    collected.sort();

    let base_path = if keep_structure {
        compute_common_ancestor(&collected)
    } else {
        None
    };

    let output_root: Option<PathBuf> = output_dir.map(|s| PathBuf::from(s));

    let num_threads = if threads == 0 { num_cpus() } else { threads };
    let pool = rayon::ThreadPoolBuilder::new().num_threads(num_threads).build().unwrap();

    let min_savings = min_savings_raw.as_ref().map(|s| parse_min_savings_value(s));

    let results: Arc<Mutex<Vec<FileResult>>> = Arc::new(Mutex::new(Vec::new()));

    let format_str_clone = format_str.clone();
    let suffix_clone = suffix.clone();
    let overwrite_clone = overwrite_str.clone();
    let output_root_clone = output_root.clone();
    let base_path_clone = base_path.clone();

    pool.install(|| {
        collected.par_iter().for_each(|input_path| {
            let res = process_one(
                input_path,
                &format_str_clone,
                suffix_clone.as_deref(),
                &overwrite_clone,
                min_savings.clone(),
                same_folder,
                output_root_clone.as_ref(),
                base_path_clone.as_ref(),
                keep_structure,
                dry_run,
                quality,
                max_size,
                keep_dates,
            );
            results.lock().unwrap().push(res);
        });
    });

    let mut results = Arc::try_unwrap(results).unwrap().into_inner().unwrap();
    results.sort_by(|a,b| a.input_path.cmp(&b.input_path));

    let mut total_input: u64 = 0;
    let mut total_output: u64 = 0;
    let mut success_count = 0;
    let mut skipped_count = 0;
    let mut error_count = 0;

    for r in &results {
        total_input += r.input_size;
        match r.status {
            Status::Success => {
                total_output += r.output_size;
                success_count += 1;
            }
            Status::Skipped => {
                total_output += r.input_size;
                skipped_count += 1;
            }
            Status::Error => {
                error_count += 1;
            }
        }
    }

    if !quiet && verbose_level >= 1 {
        for r in &results {
            match r.status {
                Status::Success => {
                    if verbose_level >= 3 {
                        println!("[Success] {} -> {}", r.input_path.display(), r.output_path.display());
                        let input_h = format_size(r.input_size);
                        let output_h = format_size(r.output_size);
                        let diff = r.output_size as i64 - r.input_size as i64;
                        let diff_h = format_size_signed(diff);
                        let percent = if r.input_size == 0 { 0.0 } else { (diff as f64 / r.input_size as f64) * 100.0 };
                        println!("{} -> {} [{} | {:+.2}%]", input_h, output_h, diff_h, percent);
                        println!();
                    }
                }
                Status::Skipped => {
                    if verbose_level >= 2 {
                        println!("[Skipped] {} -> {}", r.input_path.display(), r.output_path.display());
                        let input_h = format_size(r.input_size);
                        println!("{} -> {} [{} | {:+.2}%]", input_h, input_h, format_size_signed(0), 0.0);
                        if let Some(msg) = &r.message {
                            println!("{}", msg);
                        }
                        println!();
                    }
                }
                Status::Error => {
                    if verbose_level >= 2 {
                        println!("[Error] {} -> {}", r.input_path.display(), r.output_path.display());
                        let input_h = format_size(r.input_size);
                        let output_h = format_size(0);
                        let diff = -(r.input_size as i64);
                        let diff_h = format_size_signed(diff);
                        println!("{} -> {} [{} | -100.00%]", input_h, output_h, diff_h);
                        if let Some(msg) = &r.message {
                            println!("{}", msg);
                        }
                        println!();
                    }
                }
            }
        }
        println!("Compressed {} files ({} success, {} skipped, {} errors)", results.len(), success_count, skipped_count, error_count);
        let total_input_h = format_size(total_input);
        let total_output_h = format_size(total_output);
        let total_diff = total_output as i64 - total_input as i64;
        let total_diff_h = format_size_signed(total_diff);
        let total_percent = if total_input == 0 { 0.0 } else { (total_diff as f64 / total_input as f64) * 100.0 };
        println!("{} -> {} [{} | {:+.2}%]", total_input_h, total_output_h, total_diff_h, total_percent);
    }
}

